func mailOperationKindLabel(ctx context.Context, operationType string) string {
	switch operationType {
	case models.MailOperationMessageMutation:
		return i18n.T(ctx, "settings.operations.type.message")
	case models.MailOperationLabelMutation:
		return i18n.T(ctx, "settings.operations.type.label")
	case models.MailOperationIMAPDraft, models.MailOperationProviderDraft:
		return i18n.T(ctx, "settings.operations.type.draft")
	case models.MailOperationSentCopy:
		return i18n.T(ctx, "settings.operations.type.sent_copy")
	default:
		return i18n.T(ctx, "settings.operations.type.other")
	}
}

func mailOperationStateLabel(ctx context.Context, operation models.MailOperationSummary) string {
	if operation.Parked {
		return i18n.T(ctx, "settings.operations.state.parked")
	}
	if operation.State == "blocked" {
		return i18n.T(ctx, "settings.operations.state.blocked")
	}
	if operation.Ambiguous {
		return i18n.T(ctx, "settings.operations.state.reconcile")
	}
	if operation.CanRetry {
		return i18n.T(ctx, "settings.operations.state.failed")
	}
	switch operation.State {
	case "failed":
		return i18n.T(ctx, "settings.operations.state.failed")
	case "pending":
		return i18n.T(ctx, "settings.operations.state.queued")
	case "processing", "syncing", "sent_copy_copying":
		return i18n.T(ctx, "settings.operations.state.in_progress")
	case "sent_copy_pending":
		return i18n.T(ctx, "settings.operations.state.waiting_copy")
	default:
		return i18n.T(ctx, "settings.operations.state.waiting")
	}
}

func mailOperationTargetLabel(operation models.MailOperationSummary) string {
	parts := make([]string, 0, 3)
	if operation.Operation != "" {
		parts = append(parts, strings.ReplaceAll(operation.Operation, "_", " "))
	}
	if operation.LabelName != "" {
		parts = append(parts, "“"+operation.LabelName+"”")
	}
	if operation.FolderName != "" {
		if operation.DestinationFolderName != "" {
			parts = append(parts, operation.FolderName+" → "+operation.DestinationFolderName)
		} else {
			parts = append(parts, operation.FolderName)
		}
	}
	if len(parts) == 0 && operation.DraftKey != "" {
		return operation.DraftKey
	}
	return strings.Join(parts, " · ")
}

func mailOperationTimeLabel(ctx context.Context, value time.Time) string {
	if value.IsZero() {
		return i18n.T(ctx, "settings.operations.not_scheduled")
	}
	return i18n.Dates(ctx).ShortDateTime(value.Local())
}

// mailOperationParkedReason says, in the page's language, why a parked
// operation can't be completed.
func mailOperationParkedReason(ctx context.Context, operation models.MailOperationSummary) string {
	switch operation.ParkedReason {
	case models.MailOperationParkedFolderRemoved:
		return i18n.T(ctx, "settings.operations.parked.folder_removed")
	default:
		return operation.LastError
	}
}

// mailOperationParkedSince is when an operation was parked. Rows that don't
// keep an update time fall back to when they were queued.
func mailOperationParkedSince(ctx context.Context, operation models.MailOperationSummary) string {
	since := operation.UpdatedAt
	if since.IsZero() {
		since = operation.CreatedAt
	}
	return i18n.T(ctx, "settings.operations.parked_since", "time", mailOperationTimeLabel(ctx, since))
}

// mailOperationUndoText is what the confirm dialog says undoing the operation
// does.
func mailOperationUndoText(ctx context.Context, operation models.MailOperationSummary) string {
	if operation.Type == models.MailOperationLabelMutation {
		return i18n.T(ctx, "settings.operations.undo.label")
	}
	switch operation.Operation {
	case "move":
		return i18n.T(ctx, "settings.operations.undo.move")
	case "delete":
		return i18n.T(ctx, "settings.operations.undo.delete")
	case "starred":
		return i18n.T(ctx, "settings.operations.undo.starred")
	default:
		return i18n.T(ctx, "settings.operations.undo.read")
	}
}

// mailOperationOrigin says who queued an operation, with what, and when:
// "You · Empty folder · 18/11, 14:55". Operations queued before Gofer
// recorded this have none.
func mailOperationOrigin(ctx context.Context, operation models.MailOperationSummary) string {
	if operation.ActionSource == "" || operation.ActionKind == "" {
		return ""
	}
	action := i18n.T(ctx, "settings.operations.action."+operation.ActionKind)
	at := mailOperationTimeLabel(ctx, operation.CreatedAt)
	switch {
	case operation.ActionSource == "rule" && operation.ActionRuleName != "":
		return i18n.T(ctx, "settings.operations.origin.rule", "rule", operation.ActionRuleName, "action", action, "time", at)
	case operation.ActionSource == "rule":
		return i18n.T(ctx, "settings.operations.origin.rule_deleted", "action", action, "time", at)
	default:
		return i18n.T(ctx, "settings.operations.origin.you", "action", action, "time", at)
	}
}

// mailOperationHasDetails reports whether a row offers Details: anything
// that failed or can't be completed.
func mailOperationHasDetails(operation models.MailOperationSummary) bool {
	return operation.LastError != "" || operation.Parked
}

// mailOperationDetail is one line of an operation's Details.
type mailOperationDetail struct {
	Label, Value string
	Code         bool
}

// mailOperationDetails lists what Details shows, in order. Times an
// operation doesn't keep are left out, and so is the next try of work that
// won't be tried again.
func mailOperationDetails(ctx context.Context, operation models.MailOperationSummary) []mailOperationDetail {
	details := []mailOperationDetail{}
	if operation.LastError != "" {
		details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.error"), Value: operation.LastError, Code: true})
	}
	if !operation.CreatedAt.IsZero() {
		details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.queued"), Value: mailOperationTimeLabel(ctx, operation.CreatedAt)})
	}
	if !operation.UpdatedAt.IsZero() {
		details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.last_change"), Value: mailOperationTimeLabel(ctx, operation.UpdatedAt)})
	}
	details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.attempts"), Value: i18n.Number(ctx, operation.Attempts)})
	if !operation.Parked {
		details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.next_try"), Value: mailOperationTimeLabel(ctx, operation.NextRetryAt)})
	}
	details = append(details, mailOperationDetail{Label: i18n.T(ctx, "settings.operations.details.reference"), Value: operation.ID, Code: true})
	return details
}

// mailOperationDetailsText is what Copy details puts on the clipboard: the
// row and its Details as plain text, ready to paste into a bug report.
func mailOperationDetailsText(ctx context.Context, operation models.MailOperationSummary) string {
	lines := []string{
		mailOperationKindLabel(ctx, operation.Type) + " · " + mailOperationStateLabel(ctx, operation),
		i18n.T(ctx, "settings.operations.details.account") + ": " + operation.AccountEmail,
	}
	if target := mailOperationTargetLabel(operation); target != "" {
		lines = append(lines, i18n.T(ctx, "settings.operations.details.change")+": "+target)
	}
	if origin := mailOperationOrigin(ctx, operation); origin != "" {
		lines = append(lines, origin)
	}
	if operation.Parked {
		lines = append(lines, mailOperationParkedReason(ctx, operation))
	}
	for _, detail := range mailOperationDetails(ctx, operation) {
		lines = append(lines, detail.Label+": "+detail.Value)
	}
	return strings.Join(lines, "\n")
}

func mailOperationActionLabel(ctx context.Context, operation models.MailOperationSummary) string {
	if operation.CanReconcile {
		return i18n.T(ctx, "settings.operations.reconcile_now")
	}
	return i18n.T(ctx, "settings.operations.retry_now")
}

// MailOperationGroupChangesLimit is how many of an action's changes its
// message list shows.
const MailOperationGroupChangesLimit = 100

// mailOperationURL is where a change's own Retry or Undo posts.
func mailOperationURL(operationID, verb string) string {
	return "/api/mail-operations/" + url.PathEscape(operationID) + "/" + verb
}

// mailActionURL is where a group's Retry or Undo posts.
func mailActionURL(actionID, verb string) string {
	return "/api/mail-operations/actions/" + url.PathEscape(actionID) + "/" + verb
}

// mailOperationListItem is one row of the list: a group, or a change with no
// recorded action.
type mailOperationListItem struct {
	Group     *models.MailOperationGroup
	Operation *models.MailOperationSummary
}

// mailOperationListItems puts groups and single changes in one order: those
// that need attention first, then the most recently changed.
func mailOperationListItems(list models.MailOperationsList) []mailOperationListItem {
	items := make([]mailOperationListItem, 0, list.Total())
	for i := range list.Groups {
		items = append(items, mailOperationListItem{Group: &list.Groups[i]})
	}
	for i := range list.Operations {
		items = append(items, mailOperationListItem{Operation: &list.Operations[i]})
	}
	attention := func(item mailOperationListItem) bool {
		if item.Group != nil {
			return item.Group.NeedsAttention()
		}
		return item.Operation.NeedsAttention()
	}
	updated := func(item mailOperationListItem) time.Time {
		if item.Group != nil {
			return item.Group.UpdatedAt
		}
		return item.Operation.UpdatedAt
	}
	slices.SortStableFunc(items, func(a, b mailOperationListItem) int {
		if attention(a) != attention(b) {
			if attention(a) {
				return -1
			}
			return 1
		}
		return updated(b).Compare(updated(a))
	})
	return items
}

// mailOperationFolderName is a folder as the sidebar names it. A folder Gofer
// no longer has is "a deleted folder"; no folder at all is "".
func mailOperationFolderName(ctx context.Context, folderID, name, role string) string {
	if folderID == "" {
		return ""
	}
	if name == "" {
		return i18n.T(ctx, "settings.operations.group.deleted_folder")
	}
	return i18n.FolderName(ctx, role, name)
}

// mailOperationGroupKinds are the actions whose title only needs how many
// messages they changed.
var mailOperationGroupKinds = map[string]bool{
	"archive": true, "unarchive": true, "delete": true, "mark_read": true, "mark_unread": true,
	"star": true, "unstar": true, "spam": true, "not_spam": true, "move": true,
	"label_add": true, "label_remove": true,
}

// mailOperationGroupCount is how many messages the action changed, or its
// changes when they have no message.
func mailOperationGroupCount(group models.MailOperationGroup) int {
	if group.Messages > 0 {
		return group.Messages
	}
	return group.Jobs
}

// mailOperationGroupTitle says what the action does, in plain words: "Move 3
// messages from Inbox to Archive", "Empty Trash". A folder or label is named
// only when every change shares it.
func mailOperationGroupTitle(ctx context.Context, group models.MailOperationGroup) string {
	count := mailOperationGroupCount(group)
	from := mailOperationFolderName(ctx, group.FolderID, group.FolderName, group.FolderRole)
	to := mailOperationFolderName(ctx, group.DestinationFolderID, group.DestinationName, group.DestinationRole)
	key := "settings.operations.group.title." + group.ActionKind
	switch group.ActionKind {
	case "empty_folder", "mark_folder_read":
		if from == "" {
			return i18n.T(ctx, key)
		}
		return i18n.T(ctx, key+".folder", "folder", from)
	case "move":
		switch {
		case from != "" && to != "":
			key += ".from_to"
		case to != "":
			key += ".to"
		}
	case "label_add", "label_remove":
		if group.LabelName != "" {
			key += ".label"
		}
	default:
		if !mailOperationGroupKinds[group.ActionKind] {
			key = "settings.operations.group.title.other"
		}
	}
	return i18n.N(ctx, key, count, "from", from, "to", to, "label", group.LabelName)
}

// mailOperationGroupState is the one state a group shows: the worst of its
// changes.
func mailOperationGroupState(ctx context.Context, group models.MailOperationGroup) string {
	switch {
	case group.Failed > 0:
		return i18n.T(ctx, "settings.operations.state.failed")
	case group.Parked > 0:
		return i18n.T(ctx, "settings.operations.state.parked")
	case group.Blocked > 0:
		return i18n.T(ctx, "settings.operations.state.blocked")
	case group.Active > 0:
		return i18n.T(ctx, "settings.operations.state.in_progress")
	default:
		return i18n.T(ctx, "settings.operations.state.queued")
	}
}

// mailOperationGroupProblems says how many of the action's changes need
// attention, and why: "2 of 340 changes failed".
func mailOperationGroupProblems(ctx context.Context, group models.MailOperationGroup) []string {
	problems := []string{}
	if group.Failed > 0 {
		problems = append(problems, i18n.N(ctx, "settings.operations.group.failed", group.Failed, "total", group.Jobs))
	}
	if group.Parked > 0 {
		problems = append(problems, i18n.N(ctx, "settings.operations.group.parked", group.Parked, "total", group.Jobs))
	}
	if group.Blocked > 0 {
		problems = append(problems, i18n.N(ctx, "settings.operations.group.blocked", group.Blocked, "total", group.Jobs))
	}
	return problems
}

// mailOperationGroupAccount is the account the action changed, or how many.
func mailOperationGroupAccount(ctx context.Context, group models.MailOperationGroup) string {
	if group.Accounts > 1 {
		return i18n.N(ctx, "settings.operations.group.accounts", group.Accounts)
	}
	return group.AccountEmail
}

// mailOperationGroupOrigin says who started the action, and when.
func mailOperationGroupOrigin(ctx context.Context, group models.MailOperationGroup) string {
	at := mailOperationTimeLabel(ctx, group.CreatedAt)
	switch {
	case group.ActionSource == "rule" && group.ActionRuleName != "":
		return i18n.T(ctx, "settings.operations.group.origin.rule", "rule", group.ActionRuleName, "time", at)
	case group.ActionSource == "rule":
		return i18n.T(ctx, "settings.operations.group.origin.rule_deleted", "time", at)
	default:
		return i18n.T(ctx, "settings.operations.group.origin.you", "time", at)
	}
}

// mailOperationChangeSubject is a message as the list names it. A message
// Gofer no longer has is said so.
func mailOperationChangeSubject(ctx context.Context, change models.MailOperationGroupMessage) string {
	switch {
	case change.Subject != "":
		return change.Subject
	case change.FromEmail == "" && change.FromName == "":
		return i18n.T(ctx, "settings.operations.group.message_gone")
	default:
		return i18n.T(ctx, "mail.no_subject")
	}
}

// mailOperationChangeFolders is where one change moves its message, or the
// folder it is in, as the sidebar names them.
func mailOperationChangeFolders(ctx context.Context, change models.MailOperationGroupMessage) string {
	from := mailOperationFolderName(ctx, change.Operation.FolderID, change.FolderName, change.FolderRole)
	to := mailOperationFolderName(ctx, change.Operation.DestinationFolderID, change.DestinationName, change.DestinationRole)
	switch {
	case from != "" && to != "" && from != to:
		return from + " → " + to
	case to != "":
		return to
	default:
		return from
	}
}

// mailOperationChangesShareFolders reports whether every change in the list
// is in the same folders, so the rows don't each repeat them.
func mailOperationChangesShareFolders(changes []models.MailOperationGroupMessage) bool {
	for _, change := range changes {
		first := changes[0].Operation
		if change.Operation.FolderID != first.FolderID || change.Operation.DestinationFolderID != first.DestinationFolderID {
			return false
		}
	}
	return true
}

// mailOperationChangeSender is who sent the message, as the list shows it.
func mailOperationChangeSender(change models.MailOperationGroupMessage) string {
	if change.FromName != "" {
		return change.FromName
	}
	return change.FromEmail
}

